  captions: [[0.0, "Red lines up west of the cone and blue east of it, behind the 35-yard line. The coach and cone are in the middle of the field."], [0.6, "The coach rolls a ball about ten yards up the field."], [1.0, "Two players from each team go out and fight for it."], [3.2, "Red wins the ground ball and the coach calls \"Possession!\", so red is on offense for the whole round."], [3.4, "The next red player pops out right away and gets a free pass."], [5.0, "Free pass! Now it is 3 on 2."], [11.0, "Red has a shot and takes it: goal! The goalie went the other way."], [13.0, "The coach calls \"Release!\" The next player from each team joins: now 4 on 3."], [13.3, "The offensive player nearest the 35 goes toward the coach for the ball."], [16.0, "The coach says \"New ball!\" and gives him a free ball."], [17.0, "The offense goes again."], [23.0, "Red has a shot and takes it: the goalie makes the save."], [24.3, "The goalie has it and throws it back to the coach at the cone."], [25.0, "The coach calls \"Release!\" The next player from each team joins: now 5 on 4."], [25.3, "The offensive player nearest the 35 goes toward the coach for the ball."], [28.0, "The coach says \"Ball in!\" and gives him a free ball."], [29.0, "The offense goes again."], [34.0, "Red has a shot and takes it: goal! The goalie went the other way."], [36.0, "The coach calls \"Release a defender!\" The next defender joins to make it even: now 5 on 5."], [36.3, "The offensive player nearest the 35 goes toward the coach for the ball."], [40.0, "The coach says \"New ball!\" and gives him a free ball."], [41.0, "The offense goes again."], [46.0, "Red has a shot and takes it: goal! The goalie went the other way."], [48.32, "The coach calls \"Reset!\" and everyone goes back to the lines."]],
